const h = $json || {};
let content = h.tool_result_content_json;
let warns = h.new_warnings_json;
if (!content) {
  content = JSON.stringify([{ type: 'text', text: 'Pobranie kontekstu zadania nie powiodlo sie (blad narzedzia). Pracuj na podstawie dostepnego kontekstu i nie zglaszaj tego jako bledu.' }]);
  warns = JSON.stringify([{ source: 'session-waiter/tool-bridge-failed', err: String((h.error && (h.error.message || h.error)) || 'brak wyniku narzedzia').slice(0, 300), severity: 'WARN' }]);
}
return { json: { tool_result_content_json: content, new_warnings_json: warns || '[]', status: h.status || 'ok' } };
